// ErrorBody es el esquema único de error de C1 (components/schemas/Error).
type ErrorBody struct {
	Code      string       `json:"code"`
	Message   string       `json:"message"`
	Fields    []FieldError `json:"fields,omitempty"`
	RequestID string       `json:"request_id"`
	RetryAt   string       `json:"retry_at,omitempty"`
}

// Register registra todas las operaciones del contrato en mux. Las que tienen manejador en impl
// (por operationId) lo usan; las demás responden 501 con el esquema único de error.
func Register(mux *http.ServeMux, impl map[string]http.Handler) {
	for _, rt := range Routes {
		h, ok := impl[rt.OperationID]
		if !ok {
			h = notImplemented()
		}
		mux.Handle(rt.Method+" "+rt.Pattern, withRequestID(h))
	}
}

// RequestID devuelve el identificador de la petición (encabezado X-Request-Id).
func RequestID(r *http.Request) string {
	return r.Header.Get("X-Request-Id")
}

// withRequestID asegura un X-Request-Id en la petición y en la respuesta.
func withRequestID(h http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		id := r.Header.Get("X-Request-Id")
		if id == "" || len(id) > 64 {
			id = newRequestID()
			r.Header.Set("X-Request-Id", id)
		}
		w.Header().Set("X-Request-Id", id)
		h.ServeHTTP(w, r)
	})
}

func newRequestID() string {
	var b [12]byte
	if _, err := rand.Read(b[:]); err != nil {
		return "sin-id"
	}
	return hex.EncodeToString(b[:])
}

// WriteError responde con el esquema único de error de C1.
func WriteError(w http.ResponseWriter, r *http.Request, status int, code, message string) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(ErrorBody{Code: code, Message: message, RequestID: RequestID(r)})
}

func notImplemented() http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		WriteError(w, r, http.StatusNotImplemented, "not_implemented", "Esta operación todavía no está implementada.")
	})
}
